{"content": "#!/usr/bin/env node
/**
 * ONE-TIME migration: convert the legacy `renderers/web-components/i18n-cache/*.json` translation
 * memory into the new engine's `ui.strings` PO catalogs (`l10n/{locale}/ui.strings.po`), preserving
 * every real translation already committed there. Run once, verify output, then delete this script
 * along with the legacy cache/pipeline it reads from.
 *
 * Usage: node scripts/migrate-ui-strings-cache.mjs
 */
import { existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { extractMessagesSpace } from "../tools/i18n-engine/src/extract-messages.ts";
import { serializePo, type PoEntry } from "../tools/i18n-engine/src/po.ts";

const repoRoot = dirname(dirname(fileURLToPath(import.meta.url)));
const cacheDir = join(repoRoot, "renderers/web-components/i18n-cache");
const sourcePath = join(repoRoot, "renderers/web-components/src/i18n.json");
const l10nDir = join(repoRoot, "l10n");

const units = extractMessagesSpace(sourcePath);
const locales = readdirSync(cacheDir)
  .filter((f) => f.endsWith(".json"))
  .map((f) => f.replace(/\.json$/u, ""))
  .filter((locale) => locale !== "en"); // en is the source; nothing to migrate for it

let totalWritten = 0;
for (const locale of locales) {
  const cache: Record<string, string> = JSON.parse(
    readFileSync(join(cacheDir, `${locale}.json`), "utf8"),
  );
  const entries: PoEntry[] = [];
  for (const unit of units) {
    const cached = cache[unit.key];
    if (cached === undefined) continue; // nothing to preserve for this key/locale
    entries.push({
      msgid: unit.msgid,
      msgctxt: unit.key,
      msgstr: cached,
      references: [sourcePath.slice(repoRoot.length + 1)],
      flags: [],
      fuzzy: false,
      obsolete: false,
    });
  }
  const poPath = join(l10nDir, locale, "ui.strings.po");
  mkdirSync(dirname(poPath), { recursive: true });
  writeFileSync(poPath, serializePo(entries));
  totalWritten += entries.length;
  console.log(`  ${locale}: ${entries.length} entr${entries.length === 1 ? "y" : "ies"} -> ${poPath}`);
}

console.log(
  `\n✓ Migrated ${locales.length} locale(s), ${totalWritten} total PO entries, from ${cacheDir} to ${l10nDir}.`,
);
