{"content": "#!/usr/bin/env node
/** ONE-TIME verification: assert every migrated l10n/{locale}/ui.strings.po round-trips exactly to
 *  its source renderers/web-components/i18n-cache/{locale}.json (except the en source itself,
 *  which has no PO). Exits non-zero on any mismatch. Delete alongside migrate-ui-strings-cache.mts. */
import { readdirSync, readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { parsePo } from "../tools/i18n-engine/src/po.ts";

const repoRoot = dirname(dirname(fileURLToPath(import.meta.url)));
const cacheDir = join(repoRoot, "renderers/web-components/i18n-cache");
const l10nDir = join(repoRoot, "l10n");

const locales = readdirSync(cacheDir)
  .filter((f) => f.endsWith(".json"))
  .map((f) => f.replace(/\.json$/u, ""))
  .filter((locale) => locale !== "en");

let mismatches = 0;
for (const locale of locales) {
  const cache: Record<string, string> = JSON.parse(
    readFileSync(join(cacheDir, `${locale}.json`), "utf8"),
  );
  const entries = parsePo(readFileSync(join(l10nDir, locale, "ui.strings.po"), "utf8"));
  const byKey = new Map(entries.map((e) => [e.msgctxt, e.msgstr]));
  for (const [key, expected] of Object.entries(cache)) {
    const actual = byKey.get(key);
    if (actual !== expected) {
      mismatches++;
      console.error(`MISMATCH ${locale}.${key}: cache=${JSON.stringify(expected)} po=${JSON.stringify(actual)}`);
    }
  }
  if (byKey.size !== Object.keys(cache).length) {
    mismatches++;
    console.error(`COUNT MISMATCH ${locale}: cache has ${Object.keys(cache).length} keys, po has ${byKey.size}`);
  }
}

if (mismatches === 0) {
  console.log(`✓ All ${locales.length} migrated locales match their source cache exactly.`);
} else {
  console.error(`\n✗ ${mismatches} mismatch(es) found.`);
  process.exitCode = 1;
}
