import { fileURLToPath } from "node:url";
import { serializePo } from "../tools/i18n-engine/src/po.ts";

const repoRoot = dirname(dirname(fileURLToPath(import.meta.url)));
const surfaces = [
  { id: "cli.scaffold", cache: "packages/scaffold/i18n-cache", source: "l10n/sources/cli.scaffold.json" },
  { id: "cli.ai", cache: "ai/pantoken-ai/i18n-cache", source: "l10n/sources/cli.ai.json" },
];

for (const surface of surfaces) {
