      key,
      { message, translate: key === "wroteFile" || key === "nextStepsNav" ? "never" : "always" },
    ]),
  );
  const sourcePath = join(repoRoot, surface.source);
  mkdirSync(dirname(sourcePath), { recursive: true });
  writeFileSync(sourcePath, `${JSON.stringify(source, null, 2)}\n`);

