#!/usr/bin/env node
/** One-time migration of the scaffold and AI CLI JSON caches into keyed PO catalogs. */
import { mkdirSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { serializePo } from "../tools/i18n-engine/src/po.ts";

const repoRoot = dirname(dirname(fileURLToPath(import.meta.url)));
const surfaces = [
  { id: "cli.scaffold", cache: "packages/scaffold/i18n-cache", source: "l10n/sources/cli.scaffold.json" },
  { id: "cli.ai", cache: "ai/pantoken-ai/i18n-cache", source: "l10n/sources/cli.ai.json" },
];

for (const surface of surfaces) {
  const cacheDir = join(repoRoot, surface.cache);
  const sourceCache = JSON.parse(readFileSync(join(cacheDir, "en.json"), "utf8")) as Record<string, string>;
  const source = Object.fromEntries(
    Object.entries(sourceCache).map(([key, message]) => [
      key,
      { message, translate: key === "wroteFile" || key === "nextStepsNav" ? "never" : "always" },
    ]),
  );
  const sourcePath = join(repoRoot, surface.source);
  mkdirSync(dirname(sourcePath), { recursive: true });
  writeFileSync(sourcePath, `${JSON.stringify(source, null, 2)}\n`);

  for (const file of readdirSync(cacheDir)) {
    if (!file.endsWith(".json") || file === "en.json") continue;
    const locale = file.slice(0, -5);
    const cache = JSON.parse(readFileSync(join(cacheDir, file), "utf8")) as Record<string, string>;
    const entries = Object.entries(sourceCache).map(([key, msgid]) => ({
      msgid,
      msgctxt: key,
      msgstr: cache[key] ?? msgid,
      references: [surface.source],
      flags: [],
      fuzzy: false,
      obsolete: false,
    }));
    const poPath = join(repoRoot, "l10n", locale, `${surface.id}.po`);
    mkdirSync(dirname(poPath), { recursive: true });
    writeFileSync(poPath, serializePo(entries));
  }
  console.log(`Migrated ${surface.id}: ${Object.keys(sourceCache).length} keys`);
}

